package fr.darkvodou.facets.symmetry;

import javax.annotation.Nullable;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Deque;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * The symmetries of //sym set, each made of the transforms generated by a few mirrors.
 */
public enum SymmetryType {

    /** Point symmetry in the horizontal plane: a half turn around the vertical axis (2 blocks) */
    SIMPLE2D("simple2d", Transform.HALF_TURN_Y),
    /** Mirror through the plane perpendicular to x (2 blocks) */
    PLANX("planx", Transform.MIRROR_X),
    PLANY("plany", Transform.MIRROR_Y),
    PLANZ("planz", Transform.MIRROR_Z),
    /** Mirror through the vertical diagonal plane x = z, one of the diagonals of STAR2D (2 blocks). Command only */
    PLANXZ("planxz", false, Transform.SWAP_XZ),
    /** Mirror through the other vertical diagonal plane, x = -z (2 blocks). Command only */
    PLANZX("planzx", false, Transform.SWAP_XZ_REVERSED),
    /** PLANXZ and PLANZX together: STAR2D without PLANX and PLANZ (4 blocks). Command only */
    DIAGONAL2D("diagonal2d", false, Transform.SWAP_XZ, Transform.SWAP_XZ_REVERSED),
    /** DIAGONAL2D mirrored up and down (8 blocks). Command only */
    DIAGONAL3D("diagonal3d", false, Transform.SWAP_XZ, Transform.SWAP_XZ_REVERSED, Transform.MIRROR_Y),
    /** PLANX and PLANZ together (4 blocks) */
    CROSS2D("cross2d", Transform.MIRROR_X, Transform.MIRROR_Z),
    /** PLANX, PLANY and PLANZ together (8 blocks) */
    CROSS3D("cross3d", Transform.MIRROR_X, Transform.MIRROR_Y, Transform.MIRROR_Z),
    /** CROSS2D with the 45° diagonals (8 blocks) */
    STAR2D("star2d", Transform.MIRROR_X, Transform.MIRROR_Z, Transform.SWAP_XZ),
    /** STAR2D mirrored up and down (16 blocks) */
    STAR3D("star3d", Transform.MIRROR_X, Transform.MIRROR_Y, Transform.MIRROR_Z, Transform.SWAP_XZ),
    /** STAR3D around each of the three axes: every rotation and mirror of the cube (48 blocks) */
    MEGASTAR("megastar", Transform.MIRROR_X, Transform.MIRROR_Y, Transform.MIRROR_Z, Transform.SWAP_XZ,
            Transform.SWAP_XY);

    private final String id;
    // Shown in the menu, else only given by command
    private final boolean menu;
    // Without the identity
    private final List<Transform> transforms;

    SymmetryType(String id, Transform... generators) {
        this(id, true, generators);
    }

    SymmetryType(String id, boolean menu, Transform... generators) {
        this.id = id;
        this.menu = menu;
        this.transforms = generate(generators);
    }

    public String id() {
        return id;
    }

    /**
     * @return the transforms giving the copies of a block, without the identity
     */
    public List<Transform> transforms() {
        return transforms;
    }

    /**
     * @return the number of blocks placed for one, counting it
     */
    public int copies() {
        return transforms.size() + 1;
    }

    /**
     * @return the types shown in the menu, the others being given by command only
     */
    public static List<SymmetryType> inMenu() {
        return Arrays.stream(values()).filter(type -> type.menu).toList();
    }

    /**
     * @return the single planes, which //sym add and //sym remove take
     */
    public static List<SymmetryType> planeTypes() {
        return List.of(PLANX, PLANY, PLANZ, PLANXZ, PLANZX);
    }

    /**
     * @return whether this type is a single plane
     */
    public boolean isPlane() {
        return planeTypes().contains(this);
    }

    /**
     * @return the single planes that this type mirrors through (none for simple2d)
     */
    public List<SymmetryType> planes() {
        return planeTypes().stream().filter(this::hasPlane).toList();
    }

    /**
     * @return whether this type mirrors through the given plane
     */
    public boolean hasPlane(SymmetryType plane) {
        return transforms.contains(plane.transforms.get(0));
    }

    /**
     * The type made of this one and the plane: planx + planz is cross2d, star2d + plany is star3d.
     *
     * @return that type, or null when no type gives exactly these copies
     */
    @Nullable
    public SymmetryType withPlane(SymmetryType plane) {
        List<Transform> generators = new ArrayList<>(transforms);
        generators.add(plane.transforms.get(0));
        Set<Transform> group = Set.copyOf(generate(generators.toArray(Transform[]::new)));
        for (SymmetryType type : values()) {
            if (Set.copyOf(type.transforms).equals(group)) {
                return type;
            }
        }
        return null;
    }

    /**
     * The largest type within this one that keeps only its other planes: star3d without plany is star2d,
     * cross2d without planx is planz. Without one diagonal, the other goes too: star2d without planxz is cross2d.
     *
     * @return that type, this one when it has no such plane, or null when no plane is left or no single type
     * keeps the most of them
     */
    @Nullable
    public SymmetryType withoutPlane(SymmetryType plane) {
        if (!hasPlane(plane)) {
            return this;
        }
        List<SymmetryType> left = new ArrayList<>(planes());
        left.remove(plane);
        SymmetryType best = null;
        boolean tie = false;
        for (SymmetryType type : values()) {
            if (type == this || type.planes().isEmpty() || type.hasPlane(plane)
                    || !transforms.containsAll(type.transforms) || !left.containsAll(type.planes())) {
                continue;
            }
            int planes = type.planes().size();
            if (best == null || planes > best.planes().size()) {
                best = type;
                tie = false;
            } else if (planes == best.planes().size()) {
                tie = true;
            }
        }
        return tie ? null : best;
    }

    @Nullable
    public static SymmetryType fromId(String id) {
        String lower = id.toLowerCase(Locale.ROOT);
        for (SymmetryType type : values()) {
            if (type.id.equals(lower)) {
                return type;
            }
        }
        return null;
    }

    /**
     * @return every combination of the generators, without the identity
     */
    private static List<Transform> generate(Transform... generators) {
        Set<Transform> group = new LinkedHashSet<>();
        Deque<Transform> pending = new ArrayDeque<>();
        group.add(Transform.IDENTITY);
        pending.add(Transform.IDENTITY);
        while (!pending.isEmpty()) {
            Transform current = pending.poll();
            for (Transform generator : generators) {
                Transform next = generator.after(current);
                if (group.add(next)) {
                    pending.add(next);
                }
            }
        }
        List<Transform> result = new ArrayList<>(group);
        result.remove(Transform.IDENTITY);
        return List.copyOf(result);
    }
}
